values.content:
=You are a QA engineering AI. Analyze this bug report and provide triage information.

Return JSON:
{
  "title": "concise bug title",
  "severity": "critical/high/medium/low",
  "impact": "description of user/business impact",
  "category": "UI/Backend/API/Database/Performance/Security/Integration",
  "affected_component": "best guess of affected system component",
  "reproducibility": "always/sometimes/rare/unknown",
  "suggested_priority": "P0/P1/P2/P3",
  "estimated_effort": "hours estimate (1-40)",
  "root_cause_hypothesis": "likely root cause",
  "suggested_fix": "recommended approach to fix",
  "workaround": "temporary workaround if any",
  "is_critical": true/false
}

Bug Report:
Reporter: {{ $json.body.reporter || 'Unknown' }}
Environment: {{ $json.body.environment || 'Not specified' }}
Description: {{ $json.body.description }}
Steps to Reproduce: {{ $json.body.steps || 'Not provided' }}
Expected Behavior: {{ $json.body.expected || 'Not provided' }}
Actual Behavior: {{ $json.body.actual || 'Not provided' }}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { title: 'Error parsing', severity: 'medium', is_critical: false, suggested_priority: 'P2' };
}
return [{
  json: {
    date: new Date().toISOString(),
    reporter: items[0].json.body?.reporter || 'Unknown',
    title: parsed.title || '',
    severity: parsed.severity || 'medium',
    impact: parsed.impact || '',
    category: parsed.category || '',
    affectedComponent: parsed.affected_component || '',
    reproducibility: parsed.reproducibility || 'unknown',
    priority: parsed.suggested_priority || 'P2',
    estimatedEffort: parsed.estimated_effort || '',
    rootCause: parsed.root_cause_hypothesis || '',
    suggestedFix: parsed.suggested_fix || '',
    workaround: parsed.workaround || '',
    isCritical: parsed.is_critical || false,
    originalDescription: items[0].json.body?.description || ''
  }
}];

parameters.text:
=🚨 *CRITICAL BUG REPORTED*

*{{ $json.title }}*
Severity: {{ $json.severity }} | Priority: {{ $json.priority }}

*Impact:* {{ $json.impact }}
*Category:* {{ $json.category }} ({{ $json.affectedComponent }})
*Root Cause:* {{ $json.rootCause }}

*Workaround:* {{ $json.workaround || 'None available' }}

*Reporter:* {{ $json.reporter }}
_{{ $json.date }}_
